<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/bootstrap.php';
use Artdon\MaterialCenter\Adapters\LegacyAuthAdapter;use Artdon\MaterialCenter\Security\PermissionService;use Artdon\MaterialCenter\Services\SupplierService;
header('Content-Type:application/json;charset=utf-8');header('Cache-Control:no-store');
try{$user=(new LegacyAuthAdapter())->current();$permission=new PermissionService();$permission->require($user,'material_center.supplier.manage');if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf((string)($_POST['csrf_token']??'')))throw new RuntimeException('安全令牌已过期。',419);$service=new SupplierService();$action=(string)($_POST['action']??'save_supplier');if($action==='save_supplier'){$id=$service->saveSupplier($_POST,$user->id);$message='供应商已保存';}elseif($action==='save_price'){$data=$_POST;if(isset($_POST['tiers_json']))$data['tiers']=json_decode((string)$_POST['tiers_json'],true)?:[];$id=$service->savePrice($data,$user->id);$message='价格已提交审批';}elseif($action==='approve_price'){$permission->require($user,'material_center.approve');$id=(int)$_POST['price_id'];$service->approvePrice($id,$user->id,(string)($_POST['decision']??''),(string)($_POST['comment']??''));$message='价格审批已处理';}else throw new RuntimeException('操作无效。');echo json_encode(['ok'=>true,'message'=>$message,'data'=>['id'=>$id]],JSON_UNESCAPED_UNICODE);}
catch(Throwable$e){http_response_code($e->getCode()>=400&&$e->getCode()<600?$e->getCode():422);echo json_encode(['ok'=>false,'message'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}
